    28	export async function loginAction(raw: unknown): Promise<ActionResult<SessionPrincipal>> {
    29	  const parsed = loginSchema.safeParse(raw);
    30	  if (!parsed.success) {
    31	    return toActionResult(parsed.error);
    32	  }
    33	
    34	  try {
    35	    const verdict = await consumeRateLimit(ANONYMOUS_ORG_ID, LOGIN_BUCKET);
